begin;
select plan(11);
insert into auth.users(id,email) values('00000000-0000-0000-0000-000000000042','a42@example.com'),('00000000-0000-0000-0000-000000000142','b42@example.com');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000042',true);set local role authenticated;
create temp table integrity_group as select * from create_group('Moderation');
create temp table integrity_comp as select create_competition((select id from integrity_group),'A challenge','steps',current_date+2,current_date+4,'UTC') as id;
select join_competition((select id from integrity_comp));
grant select on integrity_group,integrity_comp to authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000142',true);
select join_group((select invite_code from integrity_group));select join_competition((select id from integrity_comp));
select throws_ok($$select moderate_competition((select id from integrity_comp),'cancel','I want to cancel')$$,'P0001','only the creator or current group owner can moderate','ordinary participant cannot moderate');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000042',true);
select throws_ok($$select moderate_competition((select id from integrity_comp),'cancel','')$$,'P0001','give a moderation reason of 1 to 500 characters','reason is mandatory');
select lives_ok($$select moderate_competition((select id from integrity_comp),'remove','Repeated rule violations','00000000-0000-0000-0000-000000000142')$$,'creator removes participant with reason');
select is((select count(*)::int from competition_audit where event='removed' and reason='Repeated rule violations'),1,'moderation reason is audited');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000142',true);
select throws_ok($$select join_competition((select id from integrity_comp))$$,'P0001','you were removed from this competition','removed participant cannot self-restore');
select throws_ok($$insert into competition_audit(competition_id,event) values((select id from integrity_comp),'created')$$,'42501',null,'clients cannot forge the audit trail');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000042',true);
select lives_ok($$select moderate_competition((select id from integrity_comp),'cancel','Weather closure')$$,'creator cancels');
select lives_ok($$select moderate_competition((select id from integrity_comp),'cancel','Weather closure')$$,'cancellation retry is idempotent');
select is((select count(*)::int from competition_audit where event='cancelled'),1,'retries do not duplicate audit events');
select throws_ok($$select finalize_competition((select id from integrity_comp))$$,'P0001','cancelled competitions cannot be finalized','cancellation cannot become a result');
reset role;
select lives_ok($$delete from auth.users where id='00000000-0000-0000-0000-000000000142'$$,'account deletion and audit anonymization remain valid');
select * from finish();
rollback;
